*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;color:#293341;background:white;font-family:-apple-system,BlinkMacSystemFont,"Noto Sans KR","Malgun Gothic",Arial,sans-serif;font-size:16px}button,input{font:inherit}button{cursor:pointer}a{color:inherit;text-decoration:none}button:focus-visible,a:focus-visible{outline:2px solid #7644eb;outline-offset:2px}
.global-header{position:sticky;top:0;z-index:50;height:72px;border-bottom:1px solid #f0f1f3;background:#fff}.header-body{max-width:970px;margin:auto;display:flex;align-items:center;height:72px;gap:0}.logo{width:44px;height:30px;flex:none;margin-right:30px}.logo img{width:44px;height:30px}.navigation{display:flex;align-items:center;gap:18px;white-space:nowrap}.navigation a{font-size:16px;font-weight:700;line-height:24px}.navigation a.current{color:#252b31}.navigation a:hover{color:#6938ee}.header-search{width:328px;height:42px;border-radius:7px;background:#f5f5f7;margin-left:44px;display:flex;align-items:center;gap:8px;padding:0 14px;flex:none}.header-search .glass{font-size:21px;color:#afb1ba}.header-search input{background:none;border:0;outline:0;width:100%;font-size:14px;color:#293341}.header-search input::placeholder{color:#b6b8bf}.account{font-size:14px;margin-left:auto;white-space:nowrap}.signup{border:0;background:#713be9;color:#fff;border-radius:6px;height:36px;padding:0 13px;font-size:14px;margin-left:16px;white-space:nowrap}
.main{max-width:970px;margin:0 auto}.hero{height:235px;padding-top:48px;border-bottom:1px solid #f1f2f3;background:#fff;position:sticky;top:72px;z-index:20}.hero h1{font-size:31px;letter-spacing:-1.4px;color:#222;font-weight:730;line-height:42px;margin:0}.group-tabs{display:grid;grid-template-columns:repeat(11,86px);align-items:start;margin-top:42px;margin-left:12px}.group-tab{border:0;background:white;height:100px;width:86px;display:flex;align-items:center;gap:10px;flex-direction:column;padding:0;font-size:13px;color:#545861;white-space:nowrap}.group-tab .icon-wrap{height:57px;width:57px;display:flex;align-items:center;justify-content:center;background:#fdfdfd;border:1px solid #f8f8f8;border-radius:12px}.group-tab img{width:40px;height:40px;object-fit:contain}.group-tab.selected{font-weight:600;color:#2e3240}.group-tab.selected .icon-wrap{border:1px solid #3c3b52}
.category-layout{display:grid;grid-template-columns:323px 647px;margin-top:0;padding-bottom:80px;min-height:1200px}.left{width:323px;position:relative}.left-inner{position:sticky;top:307px;max-height:calc(100vh - 317px);overflow-y:auto;padding:24px 77px 25px 0;scrollbar-width:none}.left-inner::-webkit-scrollbar{display:none}.sub-tab{height:58px;min-height:58px;width:246px;text-align:left;padding:0 20px;border:0;background:white;color:#a7a9af;font-size:18px;font-weight:450;white-space:nowrap}.sub-tab.current{background:#f7f7f8;color:#222;font-size:19px;font-weight:700;border-radius:8px}.sub-tab:hover{color:#32323b}
.contents{min-width:0;padding-top:40px}.breadcrumb{height:43px;font-size:14px;color:#92949b;display:flex;align-items:flex-start;gap:8px}.breadcrumb a{color:#94959b}.breadcrumb b{font-weight:400;color:#62666c}.preset{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:42px;margin-bottom:45px}.preset a{height:120px;border:1px solid #f2f2f2;overflow:hidden;border-radius:12px;display:block;position:relative;background:#f5f5f8;box-shadow:0 0 1px #ccc}.preset .art{height:82px;display:flex;align-items:center;justify-content:space-between;padding:12px 15px;background:#f5f5f8}.preset .art strong{font-size:14px;line-height:22px}.preset .art span{font-size:42px;filter:drop-shadow(0 2px 1px #cdd2df)}.preset a:nth-child(2) .art{background:#f2f6f9}.preset small{font-size:13px;line-height:37px;display:block;padding-left:13px;background:white}.service-section{scroll-margin-top:330px;margin-top:0;margin-bottom:41px}.service-section h2{font-size:18px;font-weight:700;margin:0 0 13px;color:#27292e}.services{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 41px}.service-link{display:flex;min-height:48px;align-items:center;font-size:14px;line-height:21px;color:#293341;word-break:keep-all;cursor:pointer}.service-link:hover{color:#713ee9;text-decoration:underline}.service-link .arrow{display:none;font-size:11px}.service-link:hover .arrow{display:inline}.loading{padding:35px 0;color:#8a8a93;line-height:1.6}.search-hint{font-size:13px;color:#888;padding:12px 0}.count{font-size:12px;color:#7c7f86}.footer{border-top:1px solid #f1f1f1;background:#fafafa;text-align:center;padding:35px;color:#93939a;font-size:12px;line-height:1.8}.hint-strip{font-size:11px;color:#adb0b8;padding:15px 0}.status{position:fixed;bottom:15px;right:15px;background:#333;color:#fff;border-radius:7px;padding:9px 12px;font-size:12px;display:none;z-index:80}
@media(max-width:1150px){.header-body,.main{max-width:calc(100vw - 36px)}.header-search{margin-left:18px;width:min(25vw,328px)}.category-layout{grid-template-columns:30% 70%}.left{width:100%}.left-inner{padding-right:25px}.sub-tab{width:100%}.group-tabs{overflow-x:auto;display:flex;margin-left:0;scrollbar-width:none}.group-tab{flex:none}.preset{gap:20px}}
@media(max-width:720px){.global-header,.header-body{height:62px}.header-body{padding:0 9px}.logo{margin-right:12px}.navigation{gap:14px}.navigation a{font-size:13px}.navigation a:nth-child(n+3){display:none}.header-search{display:none}.account{display:none}.signup{margin-left:auto;font-size:12px}.hero{height:200px;padding-top:25px;top:62px}.hero h1{font-size:27px}.group-tabs{margin-top:22px}.category-layout{display:block}.left{width:auto}.left-inner{position:sticky;top:262px;background:white;display:flex;padding:8px 0;max-height:none;overflow:auto;border-bottom:1px solid #eee;z-index:18}.sub-tab{width:auto;flex:none;height:40px;min-height:40px;padding:0 10px;font-size:14px}.sub-tab.current{font-size:14px}.contents{padding-top:20px}.breadcrumb{height:35px}.preset{gap:9px;margin-bottom:38px}.preset .art span{font-size:26px}.preset .art strong{font-size:12px}.service-section{scroll-margin-top:330px}.services{gap:0 12px}.service-link{font-size:13px}}
.preset a:first-child .art{background:#f4f4f7 url("https://dmmj3ljielax6.cloudfront.net/upload/preset/preset_move.png") right center/auto 100% no-repeat}.preset a:nth-child(2) .art{background:#f1f5f7 url("https://dmmj3ljielax6.cloudfront.net/upload/preset/preset_atopy_care.png") right center/auto 100% no-repeat}.preset .art span{display:none}

