const groups=[{"name":"이사/청소","icon":"https://dmmj3ljielax6.cloudfront.net/upload/requestForm/d672fa5d-31c7-4a9e-b846-149f28cd021a.svg","slug":"이사-청소A"},{"name":"설치/수리","icon":"https://dmmj3ljielax6.cloudfront.net/upload/requestForm/5b536fc7-28c9-4d93-baa6-ad8c21985197.svg","slug":"설치-수리A"},{"name":"인테리어","icon":"https://dmmj3ljielax6.cloudfront.net/upload/requestForm/1b3662d5-f455-4681-88e4-b893d90aa2be.svg","slug":"인테리어A"},{"name":"외주","icon":"https://dmmj3ljielax6.cloudfront.net/upload/requestForm/0c4194a3-f50d-44f0-af72-712675e6c673.svg","slug":"외주A"},{"name":"이벤트/뷰티","icon":"https://dmmj3ljielax6.cloudfront.net/upload/requestForm/5d6ed12d-3958-4cc3-94fc-9d3ba3b0edb2.svg","slug":"이벤트-뷰티A"},{"name":"취업/직무","icon":"https://dmmj3ljielax6.cloudfront.net/upload/requestForm/38e86694-55c8-4492-aad7-6e45cee99385.svg","slug":"취업-직무A"},{"name":"과외","icon":"https://dmmj3ljielax6.cloudfront.net/upload/requestForm/3645b472-4cd9-4825-b764-84b9a7323c71.svg","slug":"과외A"},{"name":"취미/자기계발","icon":"https://dmmj3ljielax6.cloudfront.net/upload/requestForm/e547f679-6de2-41d0-9c40-b79ed3728a6f.svg","slug":"취미-자기계발A"},{"name":"자동차","icon":"https://dmmj3ljielax6.cloudfront.net/upload/requestForm/a58ac285-97ea-4b31-9c33-29eda27ef3ad.svg","slug":"자동차A"},{"name":"법률/금융","icon":"https://dmmj3ljielax6.cloudfront.net/upload/requestForm/a97aa917-4a79-420d-bcf8-fe63fc555cb5.svg","slug":"법률-금융A"},{"name":"기타","icon":"https://dmmj3ljielax6.cloudfront.net/upload/requestForm/e31a86aa-4feb-4669-8f92-75d8ef885800.svg","slug":"기타A"}];
const initial={"group":"이사/청소","sections":[{"name":"이사","items":[{"name":"가정이사(투룸 이상)"},{"name":"국내 이사"},{"name":"무진동차량/냉동차량/냉장차량"},{"name":"사무실/상업공간 이사"},{"name":"용달/화물 운송"},{"name":"원룸/소형 이사"},{"name":"상조 가전결합 상품"}]},{"name":"입주/집 청소","items":[{"name":"(긴급) 싱크대 막힘"},{"name":"이사/입주 청소업체"},{"name":"거주 청소업체"},{"name":"곰팡이 제거"},{"name":"나노코팅 시공"},{"name":"단열/결로 시공"},{"name":"라돈저감 시공"},{"name":"보일러/수도배관 청소"},{"name":"새집/헌집증후군 시공"},{"name":"입주사전점검 대행"},{"name":"정리수납 컨설팅"},{"name":"줄눈 시공"},{"name":"집청소 도우미"},{"name":"코킹 시공"},{"name":"하수구 청소"}]},{"name":"가전/가구 청소","items":[{"name":"가구 청소"},{"name":"가전제품 청소"},{"name":"냉장고 청소"},{"name":"세탁기 청소"},{"name":"소파 청소"},{"name":"시스템에어컨 청소"},{"name":"실외기 청소"},{"name":"에어컨 청소"},{"name":"온풍기/냉난방기 청소"},{"name":"침대/매트리스 청소"},{"name":"후드 청소"},{"name":"상조 가전결합 상품"}]},{"name":"사업장 청소","items":[{"name":"건물내부 청소(바닥/계단/화장실)"},{"name":"건물외부 청소(외벽/유리창)"},{"name":"계단/화장실 청소"},{"name":"닥트/환풍구 청소"},{"name":"바닥 청소(왁스 코팅)"},{"name":"사무실/상업공간 청소업체"},{"name":"시설/건물 관리"},{"name":"업소용 주방기구 판매"},{"name":"준공 청소"},{"name":"카페트 청소"}]},{"name":"특수 청소","items":[{"name":"단체 세탁"},{"name":"대기 측정 및 관리"},{"name":"물탱크/저수조 청소"},{"name":"바퀴벌레 퇴치"},{"name":"방역소독"},{"name":"벌초/예초"},{"name":"비둘기 퇴치"},{"name":"수질관리 및 녹조제거"},{"name":"악취 제거"},{"name":"유품정리/특수청소"},{"name":"침수 복구 및 청소"},{"name":"해충방역"},{"name":"화재 복구/청소"}]},{"name":"철거/폐기","items":[{"name":"철거"},{"name":"폐기물 처리"}]}],"presets":[{"name":"이사 준비 · 한번에 견적 받기 · 이사 서비스 8종","url":"https://soomgo.com/requests/preset?id=69f1ae34a4efea38cbbb3b04&location=service_category_page_click_preset_list_item"},{"name":"아토피 케어 · 한번에 견적 받기 · 청소 서비스 9종","url":"https://soomgo.com/requests/preset?id=69f1ae34a4efea38cbbb3b0c&location=service_category_page_click_preset_list_item"}]};
const root=document.querySelector.bind(document);let currentGroup="이사/청소",currentSub=null,source=initial,filterText="",sequence=0;
function esc(t){return String(t??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function toast(t){let x=root("#toast");x.textContent=t;x.style.display="block";clearTimeout(toast._t);toast._t=setTimeout(()=>x.style.display="none",3400)}
function groupURL(g){let group=groups.find(x=>x.name===g);return "https://soomgo.com/categories/"+encodeURIComponent(group?.slug||g)+"?from=main"}
function tabs(){root("#groups").innerHTML=groups.map(x=>'<button class="group-tab '+(x.name===currentGroup?'selected':'')+'" data-group="'+esc(x.name)+'"><span class="icon-wrap"><img src="'+esc(x.icon)+'" alt="'+esc(x.name)+' 아이콘"></span>'+esc(x.name)+'</button>').join("");root("#groupTitle").textContent=currentGroup}
function render(){
 tabs();
 const sections=source.sections||[];
 const filt=filterText.trim().toLocaleLowerCase();
 root("#subtabs").innerHTML=sections.map((s,i)=>'<button class="sub-tab '+((currentSub||sections[0]?.name)===s.name?'current':'')+'" data-sub="'+esc(s.name)+'">'+esc(s.name)+'</button>').join("");
 const presets=source.presets||[];
 root("#presets").style.display=(filterText||!presets.length)?"none":"grid";
 root("#presets").innerHTML=presets.slice(0,2).map((p,i)=>'<a href="'+esc(p.url||groupURL(currentGroup))+'" target="_blank" rel="noopener"><div class="art"><strong>'+esc(p.name?.split(" · ")[0]||"한번에 견적 받기")+'<br>한번에 견적 받기</strong><span>'+(i?"🧽":"📦")+'</span></div><small>'+esc(p.name?.split(" · ").at(-1)||"서비스")+"　›"+'</small></a>').join("");
 let count=0;root("#sections").innerHTML=sections.map((sec,i)=>{let items=sec.items.filter(x=>!filt||x.name.toLocaleLowerCase().includes(filt)||sec.name.toLocaleLowerCase().includes(filt));count+=items.length;if(filt&&!items.length)return '';return '<section class="service-section" id="section-'+i+'" data-name="'+esc(sec.name)+'"><h2>'+esc(sec.name)+'</h2><div class="services">'+items.map(v=>'<a class="service-link" href="/clone?service='+encodeURIComponent(v.name)+'" title="'+esc(v.name)+' · 고수찾기">'+esc(v.name)+' <span class="arrow">↗</span></a>').join("")+'</div></section>'}).join("");
 if(!count)root("#sections").innerHTML='<div class="loading">해당 조건에 맞는 서비스가 없습니다.</div><p><a href="'+groupURL(currentGroup)+'" target="_blank" rel="noopener">숨고 원본에서 보기 ↗</a></p>';
}
async function selectGroup(g){if(!groups.some(x=>x.name===g))return;currentGroup=g;currentSub=null;filterText="";root("#search").value="";source={sections:[],presets:[]};render();root("#sections").innerHTML='<p class="loading">원본 서비스 분류를 불러오고 있습니다.</p>';const token=++sequence;try{const response=await fetch('/api/categories?group='+encodeURIComponent(g),{cache:'no-store'});if(!response.ok)throw Error('HTTP '+response.status);const d=await response.json();if(token!==sequence)return;source=d;currentSub=source.sections[0]?.name||null;render();window.history.replaceState(null,'','/categories?group='+encodeURIComponent(g));}catch(e){if(token!==sequence)return;source={sections:[],presets:[]};render();root("#sections").innerHTML='<div class="loading">목록을 불러오지 못했습니다. 공식 사이트에서 직접 조회하실 수 있습니다.</div><a href="'+groupURL(g)+'" target="_blank" rel="noopener">공식 '+esc(g)+' 서비스 목록 ↗</a>';toast('분류 조회 오류: '+e.message)}}
root("#groups").addEventListener("click",e=>{const b=e.target.closest("[data-group]");if(b)selectGroup(b.dataset.group)});
root("#subtabs").addEventListener("click",e=>{const b=e.target.closest("[data-sub]");if(!b)return;currentSub=b.dataset.sub;render();const idx=source.sections.findIndex(x=>x.name===b.dataset.sub);root("#section-"+idx)?.scrollIntoView({behavior:"smooth",block:"start"})});
root("#searchForm").addEventListener("submit",e=>{e.preventDefault();filterText=root("#search").value;render();root("#sections").scrollIntoView({behavior:"smooth"})});
root("#search").addEventListener("input",e=>{filterText=e.target.value;render()});root("#join").onclick=()=>window.open('https://soomgo.com/pro?entry_point=signup_cta','_blank','noopener');
const query=new URLSearchParams(location.search).get("group");if(query&&query!=="이사/청소")selectGroup(query);else {render();selectGroup("이사/청소")}

