or:pointer}.search-row{height:92px;padding:24px 0;display:flex;gap:8px}.find-form{height:44px;border:1px solid #e9ebed;background:#f5f5f7;display:flex;align-items:center;border-radius:6px;flex:1}.magnifier{font-size:19px;color:#acb3bd;margin-left:13px}.find-form input{padding:0 12px;flex:1;min-width:0;outline:none;border:0;background:none;font-size:14px;color:#293341}.find-form input::placeholder{color:#bdc0c7}.map-btn{width:86px;flex:none;border:1px solid #e4e7e9;border-radius:5px;background:#fafafa;font-size:14px;color:#293341}.category-header{font-size:13px;color:#87909b;height:53px;display:flex;align-items:center;gap:5px;padding-top:9px}.category-header button{width:19px;height:19px;padding:0;background:white;border:1px solid #b6c0cb;border-radius:50%;font-size:12px;color:#a1aab5}.pro-card{display:flex;align-items:center;min-height:138px;padding:15px 0 13px;border-bottom:1px solid #f1f3f4;cursor:pointer;position:relative;gap:14px}.pro-card:hover .pro-name{text-decoration:underline}.pro-info{flex:1;min-width:0}.pro-name{font-size:16px;color:#293341;font-weight:700;margin:0 0 7px;line-height:20px;max-height:23px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.pro-meta{font-size:14px;color:#58606b;white-space:nowrap;margin-bottom:8px}.star{color:#ffbf00;margin-right:2px}.description{font-size:12px;color:#858d95;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;margin:0 0 7px}.tag{font-size:11px;padding:2px 4px;border-radius:2px;display:inline-block;margin-right:7px}.tag.pay{color:#6c3fe9;background:#f2eeff}.tag.rocket{color:#237ada;background:#e9f1ff}.avatar{width:64px;height:64px;flex:none;display:flex;align-items:center;justify-content:center;border-radius:14px;background:#f1f3f5;color:#adb6c0;font-size:23px;font-weight:800;overflow:hidden}.avatar img{width:100%;height:100%;object-fit:cover}.avatar:not(:has(img)){position:relative;background:#e5e9ee;color:transparent}.avatar:not(:has(img)):before{content:'';position:absolute;background:#fff;width:18px;height:18px;top:14px;border-radius:50%}.avatar:not(:has(img)):after{content:'';position:absolute;background:#fff;width:36px;height:24px;bottom:6px;border-radius:26px 26px 10px 10px}.avatar.colored{background:linear-gradient(130deg,#b8b2dc,#779ae2);color:white}.favorite{position:absolute;right:75px;top:15px;border:0;background:#fff;color:#c5c5c5;font-size:20px;visibility:hidden}.pro-card:hover .favorite{visibility:visible}.empty{color:#939ba4;text-align:center;padding:40px}.more{margin:35px auto 70px;display:block;padding:10px 22px;background:white;border:1px solid #ddd;border-radius:6px}.footer{max-width:970px;margin:100px auto 40px;font-size:12px;color:#a5a8ad;border-top:1px solid #eee;padding-top:30px}
.modal{display:none;position:fixed;inset:0;z-index:40;background:#0006;align-items:center;justify-content:center}.modal.open{display:flex}.dialog{min-width:400px;max-width:min(570px,95vw);max-height:80vh;overflow:auto;background:white;padding:25px;border-radius:12px;box-shadow:0 15px 55px #0002}.dialog h2{font-size:20px;margin:0 0 18px}.dialog input{width:100%;border:1px solid #ddd;padding:12px;border-radius:6px}.region-list,.service-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px;margin-top:15px}.region-list button,.service-list button{border:1px solid #ececec;border-radius:6px;background:#fff;padding:10px;font-size:13px;text-align:left}.region-list button:hover,.service-list button:hover{border-color:#7141ed;color:#7141ed}.dialog-close{margin-top:20px;background:#6a3bea;color:white;padding:11px 14px;border:0;border-radius:6px;width:100%}.map{display:none;width:100%;height:540px;border-radius:8px;overflow:hidden}.map.visible{display:block}.map iframe{width:100%;height:100%;border:0}.hide{display:none!important}
