scripts:
const seed=[
{name:"입주청소 전국 고용횟수 No.1 SK클린텍",rating:5,reviews:6992,hired:17447,years:14,description:"✨ 100% 직영팀(검증) · 구역별 전용 타월 · 독일 친환경 세제 사용 · 부가세 없음 · 기간 제한 없는 A/S",img:"https://static.cdn.soomgo.com/upload/profile/ef6e4743-ac7e-4f79-95ce-ee3bd3de72d7.jpg?webp=1&h=320&w=320",pay:true,rocket:true,url:"https://soomgo.com/profile/users/9375389"},
{name:"청소평점5.0!=수담클린/공동대표가직접!지휘 및 청소!",rating:5,reviews:923,hired:968,years:8,description:"🌈공동대표도 함께🌈 ✅믿음직한 청소! 저희 이름걸고 부끄럽지않게 최선을 다하겠습니다/ ✅AS보장10일✅",img:"https://static.cdn.soomgo.com/upload/profile/db2e96a8-c4ea-4677-ab99-bbb1372ccedc.jpg?webp=1&h=320&w=320",pay:true,rocket:true},
{name:"✨셀럽홈케어✨ ⭐입주/이사 청소전문업체⭐",rating:5,reviews:215,hired:70,years:5,description:"💧쓱쓱싹싹💧 🎀 셀럽홈케어 🎀 🥇고객님께 깨끗함으로 다가가겠습니다 .🥇",pay:true,rocket:true},
{name:"치우는사람들 100%최정예 직영팀 청소업체",rating:5,reviews:203,hired:331,years:7,description:"🔷청소, 비슷해 보이지만 저희 결과는 다릅니다🔷 🇩🇪키엘 친환경 세제·하청 알바❌·7일A/S👌",pay:true,rocket:true},
{name:"⭐우주대청소⭐ | 종합청소 | 상담문의 환영❣️",rating:4.9,reviews:102,hired:111,years:3,description:"⭐우주대청소⭐ | ❣️종합청소업체❣️ 고객과의 다음 만남까지 생각하여",pay:true,rocket:true},
{name:"노더티클린",rating:4.9,reviews:60,hired:138,years:8,description:"고객만족💯점을 위해 한국인 대표/팀장이 직접 서비스를 제공합니다~! 🌞No Dirty Clean🌞",pay:true,rocket:true},
{name:"구석구석 홈케어 * 입주ㅣ거주ㅣ사무실",rating:5,reviews:17,hired:82,years:10,description:"❤️ 입주청소 ㅣ 거주청소 ㅣ 이사청소 내 집을 호텔처럼!",pay:true,rocket:true},
{name:"치우리클린",rating:5,reviews:3,hired:6,years:6,description:"🧹입주·이사·정기·사무실청소까지 한 곳에서🧹",pay:true,rocket:true},
{name:"레몬트리클린",rating:5,reviews:1,years:3,description:"🍋 레몬처럼 상큼하게! 친환경 프리미엄 홈케어",coupon:true}
];
const filters=[{title:"어떤 서비스를 원하시나요?",items:[["이사청소","이전 거주자가 만든 각종 때·먼지 청소"],["입주청소","신축 건물 입주 시 청소"],["리모델링 후 청소"],["기타"]]},{title:"어떤 건물인가요?",items:[["아파트"],["빌라/연립주택"],["오피스텔"],["원룸"],["단독주택"],["사무실/상가"],["기타"]]},{title:"공간에 해당하는 항목을 선택해주세요.",items:[["해당 없음"],["베란다 확장"],["복층형 구조"],["야외 테라스"],["기타"]]},{title:"추가로 원하시는 서비스가 있나요?",items:[["없음"],["곰팡이 제거"],["외부 유리창 청소"],["새집증후군 제거"],["스티커/시트지 제거"],["기타"]]}];
const regions=["서울 성동구","서울 강북구","서울 서초구","서울 강남구","서울 마포구","서울 송파구","서울 영등포구","인천 계양구","경기 성남시","충북 청주시 서원구"];
const services=["이사/입주 청소업체","거주 청소업체","에어컨 청소","가사도우미","사무실 청소","정리수납 컨설팅","원룸/소형 이사","인테리어 시공","시스템에어컨 설치","웹 개발","보일러 설치"];
const $=s=>document.querySelector(s),escapeHtml=x=>String(x??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c])),format=n=>Number(n).toLocaleString("ko-KR");
let data=seed, term="",couponOnly=false, visible=20, currentRegion=regions[0], currentService=services[0], favorites=new Set(), selected={};
function buildFilters(){$("#filterGroups").innerHTML=filters.map((g,i)=>'<div class="filter-group '+(i===0?'first':'')+'"><h3>'+escapeHtml(g.title)+'</h3>'+g.items.map((entry,j)=>'<label class="filter-option"><input type="radio" name="filter'+i+'" value="'+escapeHtml(entry[0])+'" '+(selected[i]===entry[0]?'checked':'')+'><span>'+escapeHtml(entry[0])+(entry[1]?'<small>'+escapeHtml(entry[1])+'</small>':'')+'</span></label>').join("")+'</div>').join("")}
function rows(){const sort=$("#sort").value;let arr=data.filter(x=>(!term||(x.name+' '+x.description).toLowerCase().includes(term.toLowerCase()))&&(!couponOnly||x.coupon));if(sort==="review")arr.sort((a,b)=>(b.reviews||0)-(a.reviews||0));if(sort==="hired")arr.sort((a,b)=>(b.hired||0)-(a.hired||0));if(sort==="rating")arr.sort((a,b)=>(b.rating||0)-(a.rating||0));return arr}
function render(){const list=rows();$("#providers").innerHTML=list.length?list.slice(0,visible).map((x,i)=>'<div class="pro-card" data-i="'+data.indexOf(x)+'"><div class="pro-info"><div class="pro-name">'+escapeHtml(x.name)+'</div><div class="pro-meta"><span class="star">★</span>'+(x.rating?x.rating.toFixed(1)+' ('+format(x.reviews)+')':'')+(x.hired?' · '+format(x.hired)+'회 고용':'')+(x.years?' · 경력 '+x.years+'년':'')+'</div><div class="description">'+escapeHtml(x.description)+'</div>'+(x.pay?'<span class="tag pay">숨고페이</span>':'')+(x.rocket?'<span class="tag rocket">▣ 로켓응답</span>':'')+(x.coupon?'<span class="tag pay">5,000원 쿠폰</span>':'')+'</div><button class="favorite" data-favorite="'+data.indexOf(x)+'">'+(favorites.has(data.indexOf(x))?'♥':'♡')+'</button><div class="avatar '+(i%3===1?'colored':'')+'">'+(x.img?'<img src="'+escapeHtml(x.img)+'" alt="">':'●')+'</div></div>').join(''):'<div class="empty">선택하신 조건에 해당하는 고수가 없습니다.</div>';$("#more").style.display=list.length>visible?'block':'none'}
$("#filterGroups").addEventListener("change",e=>{if(e.target.matches('input[type=radio]')){selected[Number(e.target.name.replace("filter",""))]=e.target.value;render()}});
$("#reset").onclick=()=>{selected={};buildFilters();couponOnly=false;$("#coupon").classList.remove("on");term="";$("#query").value="";render()};
$("#find").onsubmit=e=>{e.preventDefault();term=$("#query").value.trim();render()};
$("#query").oninput=e=>{term=e.target.value.trim();render()};
$("#sort").onchange=render;$("#coupon").onclick=()=>{couponOnly=!couponOnly;$("#coupon").classList.toggle("on",couponOnly);render()};
$("#mapToggle").onclick=()=>{let map=$("#map");map.classList.toggle("visible");$("#mapToggle").textContent=map.classList.contains("visible")?"☰ 목록":"♧ 지도";$("#providers").classList.toggle("hide",map.classList.contains("visible"))};
$("#more").onclick=()=>{visible+=20;render()};
$("#join").onclick=()=>window.open("https://soomgo.com/pro","_blank","noopener");
$("#providers").addEventListener("click",e=>{let heart=e.target.closest('[data-favorite]');if(heart){const id=+heart.dataset.favorite;favorites.has(id)?favorites.delete(id):favorites.add(id);render();return}let card=e.target.closest('[data-i]');if(!card)return;const x=data[+card.dataset.i];$("#profileTitle").textContent=x.name;$("#profileStats").textContent='★ '+x.rating+' · 후기 '+format(x.reviews)+' · '+(x.hired||0)+'회 고용';$("#profileIntro").textContent=x.description;$("#profileUrl").href=x.url||'https://soomgo.com/search/pro';$("#profileModal").classList.add("open")});
function renderRegions(q=""){$("#regions").innerHTML=regions.filter(x=>x.includes(q)).map(x=>'<button data-value="'+escapeHtml(x)+'">'+escapeHtml(x)+'</button>').join("")}
function renderServices(q=""){$("#services").innerHTML=services.filter(x=>x.includes(q)).map(x=>'<button data-value="'+escapeHtml(x)+'">'+escapeHtml(x)+'</button>').join("")}
$("#placeSelect").onclick=()=>{$("#regionModal").classList.add("open");renderRegions()};$("#serviceSelect").onclick=()=>{$("#serviceModal").classList.add("open");renderServices()};
$("#regionQuery").oninput=e=>renderRegions(e.target.value);$("#serviceQuery").oninput=e=>renderServices(e.target.value);
$("#regions").onclick=e=>{let b=e.target.closest("[data-value]");if(!b)return;currentRegion=b.dataset.value;$("#regionName").textContent=currentRegion;$("#regionModal").classList.remove("open")};
$("#services").onclick=e=>{let b=e.target.closest("[data-value]");if(!b)return;currentService=b.dataset.value;$("#serviceName").textContent=currentService.length>12?currentService.slice(0,9)+'...':currentService;$("#serviceModal").classList.remove("open")};
document.querySelectorAll("[data-close]").forEach(x=>x.onclick=()=>x.closest(".modal").classList.remove("open"));
document.querySelectorAll(".modal").forEach(x=>x.onclick=e=>{if(e.target===x)x.classList.remove("open")});
const initial=new URLSearchParams(location.search).get('service');if(initial){currentService=initial;document.querySelector('#serviceName').textContent=initial.length>12?initial.slice(0,9)+'...':initial;document.querySelector('#serviceSelect').title=initial;}
buildFilters();render();

const params=new URLSearchParams(location.search);const words=['휴대폰','미용실','인테리어','입주청소','이사','도배','에어컨','철거','청소','네일','신점','보험','더보기'];let region='서초4동';let records;
const fmt=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const $=s=>document.querySelector(s);
$('#query').value=params.get('q')||'';$('#chips').innerHTML=words.map(w=>'<button class="chip '+(w==='더보기'?'more':'')+'" data-word="'+fmt(w)+'">'+fmt(w)+'</button>').join('');
const nameSeeds=[['감동상회','보쌈/족발','4.0','3','서초동 · 단골 11'],['교대 오리사냥','닭/오리 요리','4.5','11','서초동 · 단골 3'],['감돈','고기 요리','4.4','2','서초동'],['고공 서초점','고기 구이','4.9','10','서초동 · 단골 8'],['소쇄원','일반 한식','4.2','6','서초동']];
function renderBusinesses(){const imgs=records?.snapshot?.images||[];let q=$('#query').value.trim();let seeds=nameSeeds;if(q)seeds=nameSeeds.filter(x=>x.join('').includes(q));if(!seeds.length){$('#businesses').innerHTML='<div class="biz">해당 검색의 실제 업체 데이터 연결 전입니다. 원본 검색결과는 감사 서버에서 별도로 수집했습니다.</div>';return}
$('#businesses').innerHTML=seeds.map((x,i)=>{const selected=imgs.filter(y=>y.alt===x[0]);let strip=selected.map(y=>'<img src="'+fmt(y.src)+'" alt="'+fmt(y.alt)+'" loading="'+(i<2?'eager':'lazy')+'">').join('');if(!strip)strip='<span style="height:138px">업체 사진 자료 없음</span>';return '<article class="biz"><div class="biz-head"><div><span class="biz-name">'+fmt(x[0])+'</span><span class="biz-cate">'+fmt(x[1])+'</span><div class="biz-sub">'+fmt(x[4])+'</div></div><div><div class="score">★ <span>'+fmt(x[2])+'</span></div><div class="ratings">후기 '+fmt(x[3])+'</div></div></div><div class="photo-strip">'+strip+'</div><div class="desc">소개&nbsp;&nbsp;'+fmt(x[0])+' 관련 업체 소개와 방문 후기를 확인하는 공간입니다.</div></article>'}).join('')}
fetch('/artifacts/original.json').then(r=>r.json()).then(r=>{records=r;renderBusinesses()}).catch(()=>{renderBusinesses()});
$('#chips').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const w=b.dataset.word;if(w==='더보기'){return}$('#query').value=w;params.set('q',w);history.replaceState(null,'','?'+params);renderBusinesses()});
$('#search').onsubmit=e=>{e.preventDefault();params.set('q',$('#query').value);history.replaceState(null,'','?'+params);renderBusinesses()};
