;color:#5a5c60;font-size:14px;position:relative}.category.on{font-weight:700;color:#111}.category.on:after{content:"";height:2px;background:#151515;left:0;right:0;position:absolute;bottom:0}.results{padding:16px 8px 90px}.card{display:flex;gap:16px;min-height:185px;padding:8px 8px 16px;border-bottom:1px solid #e9e9e9;cursor:pointer}.card img{width:104px;height:104px;flex:none;border-radius:9px;object-fit:cover;background:#f7f7f7}.card-text{min-width:0;flex:1;padding-top:1px}.clinic{font-size:12px;color:#697683;white-space:nowrap;text-overflow:ellipsis;overflow:hidden;margin-bottom:7px}.name{font-size:14px;line-height:1.45;height:auto;max-height:42px;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;font-weight:500;margin-bottom:8px}.old{font-size:12px;color:#888;margin-bottom:3px}.old s{margin-left:4px;color:#999}.price{font-size:16px;line-height:23px;font-weight:800;color:#24262a}.price em{font-style:normal;font-weight:700;color:#fa6576;margin-right:6px}.score{margin-top:9px;color:#858b90;font-size:12px}.score b{color:#ffbe25}.tag{background:#e2f7fb;color:#0799ad;font-size:11px;display:inline-block;margin-top:6px;border-radius:3px;padding:2px 4px}.bottom{height:64px;position:fixed;bottom:0;left:600px;z-index:10;background:white;border-top:1px solid #eee;width:616px;display:grid;grid-template-columns:repeat(5,1fr)}.bottom button{background:white;border:0;color:#6b7075;font-size:11px;display:flex;gap:2px;flex-direction:column;align-items:center;justify-content:center}.bottom button .ico{font-size:21px;line-height:27px}.bottom button.active{color:#151515;font-weight:800}.empty{text-align:center;padding:55px 20px;color:#999}.more{display:block;width:calc(100% - 32px);border:1px solid #ddd;background:white;border-radius:8px;padding:14px;margin:20px auto}.overlay{display:none;position:fixed;inset:0;background:#0005;z-index:30;align-items:center;justify-content:center}.overlay.open{display:flex}.panel{width:min(616px,100vw);height:100vh;max-height:100vh;overflow-y:auto;background:#fff;position:relative;padding:0 16px}.panel-head{height:56px;display:flex;align-items:center;font-size:18px;font-weight:700;gap:20px;position:sticky;top:0;background:#fff;z-index:1}.panel-head button{background:#fff;border:0;font-size:24px}.region-grid{display:grid;grid-template-columns:170px 1fr;gap:0}.region-main{border-right:1px solid #eee;background:#f8f8f8}.region-main button,.region-sub button{display:block;width:100%;border:0;background:transparent;text-align:left;padding:14px 12px}.region-main button.on{background:#fff;color:#fb657b;font-weight:800}.region-sub button{border-bottom:1px solid #f3f3f3}.detail{padding:20px}.detail img{width:175px;height:175px;object-fit:cover;border-radius:9px}.detail h2{line-height:1.35}.detail .close{border:0;background:#eee;padding:10px 16px;border-radius:7px}.detail a{display:inline-block;background:#f96380;color:white;padding:12px;border-radius:5px}.searchbar{padding:14px 18px;display:flex;gap:10px}.searchbar input{flex:1;min-width:0;border-radius:7px;border:1px solid #ddd;padding:13px}.searchbar button{border:0;background:#f86482;color:white;border-radius:7px;padding:0 14px}.last{font-size:11px;color:#bbb;text-align:center;margin:24px 0}.foot-spacer{display:none}
