{cat:"눈성형",clinic:"팝성형외과의원",loc:"서울 압구정역",name:"팝 평생 눈성형 맛집 자연유착 세미아웃라인 인아웃라인 쌍꺼풀 매몰 앞트임 눈매교정",old:849000,price:429000,discount:49,score:9.7,reviews:19575,img:"https://image2.gnsister.com/images/direct/1792143625591_925cf148e42e487ba2af35e69fe598f4.jpg?f=webp&h=330&w=330",url:"https://unni.app/events/6554"},
{cat:"눈성형",clinic:"디에이성형외과의원",loc:"서울 역삼역",name:"디에이 눈맛집_첫눈자연유착_눈성형_쌍꺼풀 매몰 눈재수술 앞트임 성형외과 전문의",old:850000,price:429000,discount:49,score:9.7,reviews:17152,img:"https://image2.gnsister.com/images/direct/1790561111051_b3da0ce7b07d411a8a03409fbc779d4.jpg?f=webp&h=330&w=330",url:"https://unni.app/events/3957"},
{cat:"필러",clinic:"어린공주성형외과",loc:"서울 신사역",name:"대표원장님 직접시술_러블리 입술필러&입꼬리필러&입꼬리보톡스",old:239000,price:119900,discount:49,score:9.1,reviews:11548,img:"https://image2.gnsister.com/images/direct/1765763337990_b5eda4d32e594aa6a92caf3eab006681.jpg?f=webp&h=330&w=330",url:"https://unni.app/events"},
{cat:"코성형",clinic:"디에이성형외과의원",loc:"서울 역삼역",name:"디에이 자려한 코성형_비순각코수술 콧대 복코교정 보형물 코재수술",old:2139000,price:1089000,discount:49,score:9.7,reviews:11755,img:"https://image2.gnsister.com/images/direct/1790664420340_dadfb7cf2c924b8394484565d9a5d7e9.jpg?f=webp&h=330&w=330",url:"https://unni.app/events"},
{cat:"눈성형",clinic:"팝성형외과의원",loc:"서울 압구정역",name:"팝 눈재수술 맛집 절개 비절개 자연유착 과교정 소세지눈 트임 쌍꺼풀재수술",old:1430000,price:720000,discount:49,score:9.5,reviews:8274,img:"https://image2.gnsister.com/images/direct/1792567530151_ef4b48c3d96a4c12bfb59f128e817e93.jpg?f=webp&h=330&w=330",url:"https://unni.app/events"}];
let listings=events.slice(),category='전체',area='전체',keyword='',limit=20;
const cats=['전체','제모','지방·다이어트','가슴성형','치아','리프팅','모발이식','한방','필러','보톡스','안면윤곽·양악','눈성형','코성형','피부','기타'],allRegions=['서울','경기','인천','부산','대구','대전','광주','울산','충남/세종','충북','전남','전북','경남','경북','강원','제주'];
const subRegions={'서울':['서울 전체','강남역/신논현역/양재','청담/압구정/신사','선릉/삼성','논현/반포/학동','서초/교대/방배','대치/도곡/한티','홍대/합정/신촌','서울역/명동/회현','잠실/석촌/천호','왕십리/성수/건대','마곡/화곡/목동','종로/을지로/충정로','영등포/여의도/노량진','미아/도봉/노원','이태원/용산/삼각지','서울대/사당/동작','은평/상암','신도림/구로','마포/공덕','금천/가산','수서/복정/장지'], '경기':['경기 전체','성남/분당/판교','수원/용인','안양/과천','남양주/하남/구리','일산/고양','평택/오산']};
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=n=>Number(n).toLocaleString('ko-KR');
function setCategories(){$('#cats').innerHTML=cats.map(x=>'<button class="category '+(category===x?'on':'')+'" data-cat="'+esc(x)+'">'+esc(x)+'</button>').join('')}
function filtered(){let r=listings.filter(x=>(category==='전체'||x.cat===category||x.name.includes(category))&&(!keyword||(x.name+' '+x.clinic+' '+x.cat).toLowerCase().includes(keyword.toLowerCase()))&&(area==='전체'||area==='서울'||x.loc.includes(area)));let sort=$('#sort').value;if(sort==='low')r.sort((a,b)=>a.price-b.price);if(sort==='high')r.sort((a,b)=>b.price-a.price);if(sort==='discount')r.sort((a,b)=>b.discount-a.discount);if(sort==='review')r.sort((a,b)=>b.reviews-a.reviews);if(sort==='rating')r.sort((a,b)=>b.score-a.score);return r}
function render(){setCategories();const r=filtered();$('#cards').innerHTML=r.length?r.slice(0,limit).map(x=>'<a class="card" href="'+esc(x.url)+'" data-id="'+listings.indexOf(x)+'"><img alt="'+esc(x.name)+'" src="'+esc(x.img)+'"><div class="card-text"><div class="clinic">'+esc(x.loc)+' · '+esc(x.clinic)+'</div><div class="name">'+esc(x.name)+'</div><div class="old">VAT 포함 <s>'+num(x.old)+'원</s></div><div class="price"><em>'+x.discount+'%</em>'+num(x.price)+'원</div><div class="score"><b>★</b> '+x.score+' ('+num(x.reviews)+')</div></div></a>').join(''):'<div class="empty">해당 조건의 공개 이벤트가 없습니다.</div>';$('#more').style.display=r.length>limit?'block':'none'}
const overlay=id=>$('#'+id).classList.add('open');
$('#cats').onclick=e=>{const b=e.target.closest('[data-cat]');if(!b)return;category=b.dataset.cat;render()};
$('#sort').onchange=render;$('#more').onclick=()=>{limit+=20;render()};$('#openSearch').onclick=()=>overlay('searchOverlay');$('#back').onclick=()=>location.href='/clone';$('#login').onclick=()=>alert('로그인/가입은 강남언니 공식 서비스에서 진행됩니다.');$('#placeSelect').onclick=()=>{drawRegions('서울');overlay('regionOverlay')};
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('.overlay').classList.remove('open'));
function drawRegions(group){$('#regionMain').innerHTML=allRegions.map(x=>'<button class="'+(group===x?'on':'')+'" data-main="'+esc(x)+'">'+esc(x)+'</button>').join('');const subs=subRegions[group]||[group+' 전체'];$('#regionSub').innerHTML=subs.map(x=>'<button data-area="'+esc(x)+'">'+esc(x)+'</button>').join('')}
$('#regionMain').onclick=e=>{const b=e.target.closest('[data-main]');if(b)drawRegions(b.dataset.main)};
$('#regionSub').onclick=e=>{const b=e.target.closest('[data-area]');if(!b)return;const v=b.dataset.area;area=v.includes('전체')?'전체':v.split('/')[0];$('#placeSelect').textContent=v+' ﹀';$('#regionOverlay').classList.remove('open');render()};
$('#searchForm').onsubmit=e=>{e.preventDefault();keyword=$('#searchInput').value.trim();$('#searchOverlay').classList.remove('open');render()};
$('#cards').onclick=e=>{const link=e.target.closest('[data-id]');if(!link)return;e.preventDefault();const x=listings[+link.dataset.id];$('#detailImage').src=x.img;$('#detailTitle').textContent=x.name;$('#detailClinic').textContent=x.loc+' · '+x.clinic;$('#detailPrice').textContent=num(x.price)+'원';$('#detailReview').textContent='★ '+x.score+' ('+num(x.reviews)+')';$('#detailLink').href=x.url;overlay('detailOverlay')};
function classify(name){if(/눈성형|쌍꺼풀|눈재수술|눈매교정|트임/.test(name))return'눈성형';if(/코성형|콧대|복코/.test(name))return'코성형';if(/필러/.test(name))return'필러';if(/보톡스/.test(name))return'보톡스';if(/지방|다이어트/.test(name))return'지방·다이어트';if(/리프팅|울쎄라/.test(name))return'리프팅';if(/가슴/.test(name))return'가슴성형';return'기타'}
async function sync(){try{const d=await fetch('/artifacts/original.json',{cache:'no-store'}).then(r=>r.ok?r.json():null);if(!d?.snapshot)return;const s=d.snapshot;const links=s.controls.filter(c=>c.tag==='A'&&c.href&&/^\/events\/[0-9]/.test(c.href));const items=[];for(const link of links){const name=link.text.trim(),ix=s.bodyText.indexOf(name);if(ix<0)continue;const chunk=s.bodyText.slice(ix+name.length,ix+name.length+1400);const clinic=chunk.match(/(?:서울|경기|인천|부산|대구|대전|광주|울산|경남|전북|제주)[^\n]{3,100}/);const price=chunk.match(/VAT 포함\s*([\d,]+)원\s*(\d+)%\s*([\d,]+)원\s*([\d.]+)\s*\(([\d,]+)\)/);const img=s.images.find(i=>i.alt?.trim()===name);if(!img||!price)continue;let loc='서울',hospital='';if(clinic){let parts=clinic[0].split('・');loc=parts[0]||loc;hospital=parts[1]||''}items.push({cat:classify(name),clinic:hospital,loc,name,old:Number(price[1].replaceAll(',','')),discount:Number(price[2]),price:Number(price[3].replaceAll(',','')),score:Number(price[4]),reviews:Number(price[5].replaceAll(',','')),img:img.src,url:'https://unni.app'+link.href})}if(items.length>=5){listings=items;render()}}catch(e){console.warn('original snapshot parse:',String(e))}}
const p=new URLSearchParams(location.search);if(p.get('q')){keyword=p.get('q');$('#searchInput').value=keyword}
