let items=fallback.map(x=>({...x}));const categoryLabels=["전체","맛동여지도","전 업종","공연·이벤트","식당","레저","여행","상시","오픈예정"];let selected="전체";
const $=s=>document.querySelector(s);function escapeHtml(s){return String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function showable(x){if(selected==="전체")return true;if(selected==="상시")return x.date==="상시";if(selected==="오픈예정")return x.badges?.includes("오픈예정");return x.cat===selected}
function draw(){const shown=items.filter(showable);const mode=$("#sort").value;if(mode==="latest")shown.sort((a,b)=>b.id-a.id);if(mode==="title")shown.sort((a,b)=>a.title.localeCompare(b.title,"ko"));$("#filters").innerHTML=categoryLabels.map(x=>'<button class="chip '+(x===selected?'selected':'')+'" data-filter="'+escapeHtml(x)+'">'+escapeHtml(x)+'</button>').join("");$("#count").textContent=shown.length;$("#gallery").innerHTML=shown.length?shown.map(x=>'<article class="card" role="button" tabindex="0" data-id="'+x.id+'"><div class="photo">'+(x.image?'<img alt="'+escapeHtml(x.title)+'" src="'+escapeHtml(x.image)+'" loading="'+(x.id<7?'eager':'lazy')+'">':'')+'<div class="labels">'+(x.badges||[]).filter(y=>y==="MD Pick"||y.includes("마감임박")).map(y=>'<span class="label '+(y.includes("마감임박")?'expiring':'')+'">'+(y==="MD Pick"?'✦ ':'')+escapeHtml(y)+'</span>').join("")+'</div></div><h3 class="card-title">'+escapeHtml(x.title)+'</h3><p class="date">'+escapeHtml(x.cat)+' · '+escapeHtml(x.date)+'</p></article>').join(""):'<p class="empty">선택하신 분류의 프로모션이 없습니다.</p>'}
$("#filters").onclick=e=>{const b=e.target.closest("[data-filter]");if(!b)return;selected=b.dataset.filter;draw()};$("#sort").onchange=draw;
$("#gallery").onclick=e=>{const c=e.target.closest("[data-id]");if(!c)return;const x=items.find(x=>x.id===+c.dataset.id);$("#detailImage").src=x.image||"";$("#detailTitle").textContent=x.title;$("#detailInfo").textContent=x.cat+" · "+x.date;$("#detailUrl").href=x.link||"https://booking.map.naver.com/promotions/home";$("#modal").classList.add("open")};
$("#gallery").onkeydown=e=>{if(e.key==="Enter"&&e.target.matches("[data-id]"))e.target.click()};$("#close").onclick=()=>$("#modal").classList.remove("open");$("#modal").onclick=e=>{if(e.target===$("#modal"))$("#modal").classList.remove("open")};
async function useCaptured(){try{const r=await fetch("/artifacts/original.json",{cache:"no-store"});if(!r.ok)return;const original=await r.json();if(!original.snapshot)return;const snap=original.snapshot;
const cards=(snap.controls||[]).filter(x=>x.tag==="A"&&x.rect?.width>220&&x.rect?.height>=180&&x.text?.includes("\n")&&x.href);
const images=(snap.images||[]).filter(x=>x.naturalWidth>=400&&x.rect?.width>=200);
const refreshed=[];const cset=new Set(categoryLabels);
for(let i=0;i<cards.length;i++){let parts=cards[i].text.split("\n").map(x=>x.trim()).filter(Boolean);if(parts.length<3)continue;let date=parts.at(-1),cat=parts.at(-2),title=parts.at(-3);if(!cset.has(cat)||!title)continue;refreshed.push({id:refreshed.length+1,title,cat,date,badges:parts.slice(0,-3),image:images[i]?.src||fallback[i]?.image||"",link:cards[i].href})}
if(refreshed.length>=items.length){items=refreshed;draw()}}catch(e){console.warn("Captured promotions parsing:",String(e))}}
draw();useCaptured();
